// Склонение по числу: forms = [one, few, many] для uk/ru; [one, other, other] для en.
export function plural(lang, n, forms) {
  const k = Math.abs(n), m10 = k % 10, m100 = k % 100;
  let i;
  if (lang === 'en') i = k === 1 ? 0 : 1;
  else i = m10 === 1 && m100 !== 11 ? 0 : m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14) ? 1 : 2;
  return String(forms[i]).replaceAll('{n}', n);
}

